// 原开工/终态/实际结果一一关联，给Plan同一say会话的精确例外；失败不退成旅行成功。
#include "contact_inquiry_progress.hpp"
#include "contact_inquiry_detail.hpp"
#include "contact_inquiry_time2.hpp"
#include "contact_inquiry_receipts.hpp"
#include "resident/kernel/command_types.hpp"
namespace hanmo::resident {namespace {
using Result=Outcome<std::optional<ContactInquiryActionSource>>;
Result fail(const StableId& code,const StableId& id){return {false,{},common_failure(code,id).error};}
bool header(const CommonStore& c,const StableId& id,const StableId& kind){const auto* h=c.state().facts.find(id);return h&&h->id==id&&h->kind==kind&&h->domain==contact_inquiry_module&&contact_inquiry_detail::serial(id,kind,c.state().next_instance_id).has_value();}
bool before(const CommonStore& c,const StableId& first,const StableId& last){const auto& order=c.state().facts.order();const auto a=std::find(order.begin(),order.end(),first),b=std::find(order.begin(),order.end(),last);return a!=order.end()&&b!=order.end()&&a<b;}
}
Outcome<std::optional<ContactInquiryActionSource>> query_contact_inquiry_action(const CommonStore& common,const ContactInquiryState& state,const StableId& actor,const StableId& action,const ContactInquiryTime2Context*exact){
    if(state.version==2){if(!exact)return {false,{},common_failure("ContactInquiryExactProgressReadRequired",action,ErrorKind::unsupported_capability).error};if(&exact->common!=&common||&exact->state!=&state)return {false,{},common_failure("ContactInquiryProgressCandidateMismatch",action,ErrorKind::internal).error};auto valid=validate_contact_inquiry_time2(*exact);if(!valid.ok)return {false,{},valid.error};valid=validate_contact_inquiry_cached_results(common,&state);if(!valid.ok)return {false,{},valid.error};if(!common.actor(actor)||action.empty())return fail("InvalidContactInquiryActionQuery",actor);const ContactInquiryStarted*start=nullptr;for(const auto&row:state.started.rows())if(row.second.action_id==action){if(start)return fail("DuplicateContactInquiryAction",action);start=&row.second;}if(!start){const auto*a=common.action(action);if(a&&a->kind==contact_inquiry_action_kind)return fail("ContactInquiryActionSourceRequired",action);return {true,std::nullopt,{}};}if(start->contact.actor_id!=actor)return {true,std::nullopt,{}};ContactInquiryActionSource out;out.source_identity=common.state().identity;out.actor_id=actor;out.policy_id=start->policy_id;out.action_id=action;out.started_fact_id=start->fact_id;out.contact=start->contact;out.start_tick=start->contact.tick;auto at=read_contact_inquiry_source_moment(*exact,{contact_inquiry_module,contact_inquiry_started_kind,start->fact_id},2);if(!at.ok)return {false,{},at.error};out.actual_started_at=std::move(at.value);const auto*f=contact_inquiry_detail::finished(state,start->fact_id);if(f){out.finished_fact_id=f->fact_id;out.finished_tick=f->tick;out.success=f->success;out.reason=f->reason;out.status=f->success?"answered":"interrupted";auto end=read_contact_inquiry_source_moment(*exact,{contact_inquiry_module,contact_inquiry_finished_kind,f->fact_id},2);if(!end.ok)return {false,{},end.error};out.actual_finished_at=std::move(end.value);}else{const auto*a=common.action(action);if(!a)return fail("ContactInquiryActualActionMissing",action);out.status="active";out.remaining_ticks=a->remaining_ticks;}return {true,std::move(out),{}};}
    if(exact)return {false,{},common_failure("ContactInquiryProgressVersionMismatch",action,ErrorKind::internal).error};
    if(!common.actor(actor)||action.empty())return fail("InvalidContactInquiryActionQuery",actor);const auto* current=common.action(action);const ContactInquiryStarted* start=nullptr;for(const auto& row:state.started.rows())if(row.second.action_id==action){if(start)return fail("DuplicateContactInquiryAction",action);start=&row.second;}
    if(!start){if(current&&current->kind==contact_inquiry_action_kind)return fail("ContactInquiryActionSourceRequired",action);return {true,std::nullopt,{}};}if(start->contact.actor_id!=actor)return {true,std::nullopt,{}};
    const auto action_number=contact_inquiry_detail::serial(action,"action",common.state().next_instance_id),start_number=contact_inquiry_detail::serial(start->fact_id,contact_inquiry_started_kind,common.state().next_instance_id);
    if(state.version!=1||!action_number||!start_number||*action_number+1!=*start_number||!header(common,start->fact_id,contact_inquiry_started_kind)||!start->player_receipt)return fail("ContactInquiryActionSourceMismatch",action);
    ContactInquiryActionSource source;source.source_identity=common.state().identity;source.actor_id=actor;source.policy_id=start->policy_id;source.action_id=action;source.started_fact_id=start->fact_id;source.contact=start->contact;source.start_tick=start->contact.tick;
    const ContactInquiryFinished* finished=nullptr;for(const auto& row:state.finished.rows())if(row.second.action_id==action){if(finished)return fail("DuplicateContactInquiryCompletion",action);finished=&row.second;}
    if(finished){const auto number=contact_inquiry_detail::serial(finished->fact_id,contact_inquiry_finished_kind,common.state().next_instance_id);if(current||finished->start_fact_id!=start->fact_id||finished->tick!=start->contact.tick+1||finished->tick>common.tick()||!number||*number<=*start_number||!header(common,finished->fact_id,contact_inquiry_finished_kind)||!before(common,start->fact_id,finished->fact_id)||!finished->player_receipt)return fail("ContactInquiryCompletionSourceMismatch",action);
        if(finished->success?!finished->reason.empty():(finished->reason!="ContactInquiryParticipantUnavailable"&&finished->reason!="ContactInquiryMeetingChanged"))return fail("InvalidContactInquiryReason",action);source.finished_fact_id=finished->fact_id;source.finished_tick=finished->tick;source.success=finished->success;source.reason=finished->reason;source.status=finished->success?"answered":"interrupted";
    }else{const auto* listener=common.actor(actor);const auto* provider=common.actor(start->contact.provider_actor_id);if(!current||current->kind!=contact_inquiry_action_kind||current->actor_id!=actor||current->start_tick!=start->contact.tick||current->remaining_ticks!=1||current->participants!=std::vector<StableId>{actor,start->contact.provider_actor_id}||common.tick()!=start->contact.tick||!listener||!provider||listener->action_id!=action||provider->action_id!=action)return fail("ContactInquiryActionMismatch",action);source.status="active";source.remaining_ticks=current->remaining_ticks;}
    return {true,std::move(source),{}};
}
Outcome<std::optional<ContactInquiryActionSource>> query_contact_inquiry_completion(const CommonStore& common,const ContactInquiryState& state,const StableId& actor,const StableId& action,const ReceiptDetails& details,Integer tick,const StableId& actual_result_id,const ContactInquiryTime2Context*exact){auto source=query_contact_inquiry_action(common,state,actor,action,exact);if(!source.ok||!source.value)return source;const auto* advance=std::get_if<AdvanceDetails>(&details.data);const auto* done=advance?advance->completed_actions.find(action):nullptr;const auto* ended=state.finished.find(source.value->finished_fact_id);
    if(!done||!ended||!ended->player_receipt||source.value->status=="active"||(state.version==2?source.value->finished_tick>tick:source.value->finished_tick!=tick)||!done->ok||done->completed!=std::optional<bool>{true}||done->success!=std::optional<bool>{source.value->success}||done->code!=std::optional<StableId>{source.value->success?StableId{"ContactInquiryAnswered"}:source.value->reason}||done->already_completed||done->task||done->military||done->family||done->growth||!done->military_field_order.empty())return fail("ContactInquiryCompletionReceiptMismatch",action);
    // Plan提交尾传真正已分配的result_id；details可能是原apply值，不能用对象地址误拒合法复制。
    const auto& binding=*ended->player_receipt;const auto* result=common.state().results.find(binding.request_actor_id+":"+std::to_string(binding.request_sequence));if(!result||!*result||(*result)->result_id!=binding.result_id||(*result)->revision!=binding.result_revision||(*result)->tick!=tick||!(*result)->details||actual_result_id!=binding.result_id)return fail("ContactInquiryActualCompletionResultRequired",action);return source;
}
}
